def clean(df):
    df = df.copy()
    # fix sex label variant (trailing space)
    if 'sex' in df.columns:
        df['sex'] = df['sex'].where(df['sex'].isna(), df['sex'].astype(str).str.strip())
    # fix body_mass_g text numbers with commas
    if 'body_mass_g' in df.columns:
        df['body_mass_g'] = pd.to_numeric(df['body_mass_g'].astype(str).str.replace(',', '', regex=False), errors='coerce')
    # fix flipper_length_mm negatives (sign error) - abs makes them in-range 170-235
    if 'flipper_length_mm' in df.columns:
        df['flipper_length_mm'] = pd.to_numeric(df['flipper_length_mm'], errors='coerce').abs()
    return df

def answer(df):
    df = clean(df)
    if 'species' not in df.columns or 'body_mass_g' not in df.columns:
        return {}
    # ensure body_mass_g numeric
    df['body_mass_g'] = pd.to_numeric(df['body_mass_g'], errors='coerce')
    grouped = df.dropna(subset=['species']).groupby('species', dropna=True)['body_mass_g'].sum()
    return {str(k): float(v) for k, v in grouped.items()}
